h1, h2 {
  font-family: Georgia, serif;
  color: #0f172a;
}

h1 {
  font-size: 2.25rem;
}

p {
  line-height: 1.6;
}

/* Site-wide typography.
   Edit the body rule to change the default font. */
body {
  font-family: system-ui, sans-serif; /* falls back to any sans-serif font */
  line-height: 1.5;
}

/* Temporarily disabled:
h1 { color: red; }
*/

.card h2 {
  font-weight: 700;
  font: 1.25rem Georgia, serif; /* resets font-weight to normal! */
}

/* Write the shorthand first, then the longhand you want to keep */
.card h2 {
  font: 1.25rem Georgia, serif;
  font-weight: 700;
}

p {
  colour: red;          /* unknown property: ignored */
  font-size: 18px       /* missing semicolon... */
  line-height: 1.5;     /* ...so this declaration is swallowed too */
  color: green;         /* valid: applied */
}

.card {
  padding: 1rem;
  border: 1px solid #cbd5e1;

  h2 {
    margin-top: 0;
  }

  &:hover {
    border-color: #1d4ed8;
  }
}
